fn test_csv_rfc4180_headers_and_row_count() {
    let ds = canonical_cruise_dataset();
    let exporter = CsvExporter::default();
    let bytes = exporter.export_to_vec(&ds).expect("CSV export failed");

    let (headers, rows) = validate_rfc4180(&bytes);

    assert_eq!(headers.len(), 46, "Header must have exactly 46 canonical columns");
    assert_eq!(rows.len(), 600, "Dataset with 600 points must emit 600 rows");

    // Total line count in raw text
    let text = std::str::from_utf8(&bytes).unwrap();
    let lines: Vec<&str> = text.split("\r\n").filter(|l| !l.is_empty()).collect();
    assert_eq!(lines.len(), 601, "Total lines must be 601 (1 header + 600 data rows)");

    // Verify first header and last header
    assert_eq!(headers[0], "Time(millisecond)");
    assert_eq!(headers[45], "APP.tip");
}

