"//! Integration test suite for RFC 7946 GeoJSON and Flight Summary JSON Exporters (12 test cases).

mod common;

use common::mock_data::*;
use flightreader_export::exporters::{
    FlightExporterExt, GeoJsonExporter, GeoJsonOptions, JsonSummaryExporter,
};
use serde_json::Value;

#[test]
fn test_geojson_valid_json_rfc8259() {
    let ds = canonical_cruise_dataset();
    let exporter = GeoJsonExporter::default();
    let json_str = exporter.export_to_string(&ds).expect("GeoJSON export failed");

    let val: Value = serde_json::from_str(&json_str).expect("GeoJSON must be valid RFC 8259 JSON");
    assert!(val.is_object());
}

#[test]
fn test_geojson_featurecollection_root_structure() {
    let ds = canonical_cruise_dataset();
    let exporter = GeoJsonExporter::default();
    let json_str = exporter.export_to_string(&ds).expect("GeoJSON export failed");

    let root: Value = serde_json::from_str(&json_str).unwrap();
    assert_eq!(root["type"], "FeatureCollection");
    assert!(root["features"].is_array());
    assert!(!root["features"].as_array().unwrap().is_empty());
}

